ARM = a(S + '/suite/armonia-maquina.html?lang=nl', 'harmoniemachine')
SC = S + '/apps/mm-score-page.html?demo&file=../suite/demos/'
EST = a(SC + 'estrellita.mmf&page', '„Altijd is Kortjakje ziek”')
SEI = a(SC + 'seikilos.mmf&page', 'het lied van Seikilos')
E1 = 'kinderen van 8 tot 12 jaar'; E2 = 'kinderen van 9 tot 14 jaar'
